<script setup lang="ts">
import { onMounted, ref, reactive } from 'vue'; import { useRoute } from 'vue-router'; import { ShoppingBag, Star, ShieldCheck } from 'lucide-vue-next'; import { http, errorMessage } from '../../api/http'; import { useCart } from '../../stores/cart'; import { useAuth } from '../../stores/auth'; import type { Product, Review, Page } from '../../types'; import { money, dateTime } from '../../utils/format'; import ProductCard from '../../components/ProductCard.vue'; import LoadingState from '../../components/LoadingState.vue'; import Pagination from '../../components/Pagination.vue'; import BookCover from '../../components/BookCover.vue'
const route = useRoute(), cart = useCart(), auth = useAuth(), product = ref<Product>(), related = ref<Product[]>([]), reviews = ref<Page<Review>>(), image = ref(''), qty = ref(1), error = ref(''), success = ref(''), loading = ref(true), busy = ref(false), editing = ref(false), review = reactive({ rating: 5, comment: '' });
async function loadReviews(page = 1) { reviews.value = (await http.get<Page<Review>>(`/products/${route.params.id}/reviews`, { params: { page } })).data }
async function load() { loading.value = true; error.value = ''; try { product.value = (await http.get<Product>(`/products/${route.params.id}`)).data; image.value = product.value.images[0] || '/fallback.svg'; await loadReviews(); related.value = (await http.get<Page<Product>>('/products', { params: { categoryId: product.value.categoryId, pageSize: 5 } })).data.items.filter(p => p.id !== product.value!.id).slice(0, 4) } catch (e) { error.value = errorMessage(e) } finally { loading.value = false } }
function add() { error.value = ''; try { cart.add(product.value!, qty.value); success.value = 'Đã thêm sách vào giỏ hàng.' } catch (e) { error.value = errorMessage(e) } }
async function saveReview() { busy.value = true; error.value = ''; try { await http[editing.value ? 'put' : 'post'](`/products/${route.params.id}/reviews${editing.value ? '/me' : ''}`, review); success.value = 'Đã lưu đánh giá.'; await load(); review.comment = ''; editing.value = false } catch (e) { error.value = errorMessage(e) } finally { busy.value = false } } onMounted(load)
</script>
<template><div class="container page"><nav class="breadcrumb"><RouterLink to="/">Trang chủ</RouterLink> / <RouterLink to="/products">Sách</RouterLink> / <span>{{ product?.name || 'Chi tiết' }}</span></nav><LoadingState v-if="loading" /><p v-if="error" class="alert error" role="alert">{{ error }}</p><p v-if="success" class="alert success" role="status">{{ success }}</p><template v-if="product && !loading"><section class="product-detail"><div><div class="detail-image"><BookCover :book="product" :image="image" eager /></div><div class="thumbnails"><button v-for="url in product.images" :key="url" :class="{ selected: image === url }" :aria-label="`Xem ảnh ${product.name}`" :aria-pressed="image === url" @click="image = url"><BookCover :book="product" :image="url" /></button></div></div><div class="detail-copy"><RouterLink :to="`/products?categoryId=${product.categoryId}`" class="eyebrow">{{ product.categoryName }}</RouterLink><h1>{{ product.name }}</h1><p>Tác giả: <strong>{{ product.author }}</strong></p><p v-if="product.averageRating" class="rating"><Star :size="17" fill="currentColor" /> {{ product.averageRating.toFixed(1) }} / 5 · {{ product.reviewCount }} đánh giá</p><p v-else class="muted">Chưa có đánh giá</p><div class="detail-price">{{ money(product.price) }}</div><dl><div><dt>Nhà xuất bản</dt><dd>{{ product.publisher }}</dd></div><div><dt>Mã sách</dt><dd>{{ product.sku }}</dd></div><div><dt>Tình trạng</dt><dd :class="product.stockQuantity && product.isActive ? 'success' : 'error'">{{ !product.isActive ? 'Ngừng bán' : product.stockQuantity ? `Còn ${product.stockQuantity} cuốn` : 'Hết hàng' }}</dd></div></dl><div class="purchase-row"><label for="quantity">Số lượng<input id="quantity" v-model.number="qty" type="number" min="1" :max="product.stockQuantity" :disabled="!product.stockQuantity"></label><button class="btn" :disabled="!product.isActive || !product.stockQuantity" @click="add"><ShoppingBag :size="19" /> Thêm vào giỏ</button></div><p class="detail-assurance"><ShieldCheck :size="19" /> Thanh toán giả lập · Phí giao hàng 0đ</p></div></section><section class="detail-section"><h2>Về cuốn sách này</h2><p class="description-text">{{ product.description }}</p></section><section class="detail-section"><h2>Đánh giá từ bạn đọc <span class="muted">({{ product.reviewCount }})</span></h2><p v-if="!reviews?.totalItems" class="muted">Chưa có đánh giá. Hãy chia sẻ sau khi hoàn thành đơn mua sách này.</p><article v-for="r in reviews?.items" :key="r.id" class="review"><div><strong>{{ r.fullName }}</strong><span class="rating"><Star :size="14" fill="currentColor" /> {{ r.rating }}/5</span><small>{{ dateTime(r.createdAt) }}</small></div><p>{{ r.comment }}</p><button v-if="r.userId === auth.user?.id" class="text-link" @click="editing = true; review.rating = r.rating; review.comment = r.comment">Sửa đánh giá của tôi</button></article><Pagination v-if="reviews" :page="reviews.page" :total-pages="reviews.totalPages" @change="(p: number) => loadReviews(p).catch(e => error = errorMessage(e))" /><form v-if="auth.user?.role === 'Customer'" class="review-form" @submit.prevent="saveReview"><h3>{{ editing ? 'Sửa đánh giá' : 'Chia sẻ cảm nhận của bạn' }}</h3><small>Chỉ dành cho bạn đọc đã có đơn hoàn thành chứa sách này.</small><div class="field"><label for="rating">Điểm đánh giá</label><select id="rating" v-model.number="review.rating"><option v-for="n in 5" :key="n" :value="n">{{ n }} sao</option></select></div><div class="field"><label for="review">Nội dung</label><textarea id="review" v-model="review.comment" required maxlength="1000" rows="3"></textarea></div><button class="btn" :disabled="busy">{{ busy ? 'Đang lưu…' : 'Gửi đánh giá' }}</button></form></section><section v-if="related.length" class="home-section"><div class="section-heading"><h2>Có thể bạn cũng thích</h2></div><div class="product-grid"><ProductCard v-for="p in related" :key="p.id" :product="p" /></div></section></template></div></template>